"""Kushmanda `results.json` → markdown. Generated, never typed."""

from __future__ import annotations

import json
import sys


def main(path: str) -> int:
    with open(path, encoding="utf-8") as handle:
        r = json.load(handle)
    c, t, h = r["corpus"], r["tokenizer"], r["held_out"]
    gpt2 = t.get("gpt2_tokens_per_line_held_out")
    steps = r["steps"] if isinstance(r["steps"], dict) else {"pretrain": r["steps"], "sft": 0}
    out = [
        "<!-- Generated by packages/sati/sati/lm/report.py from the training run. Do not edit by hand. -->\n",
        f"# Kushmanda — Sati's own language model (`{r['model']}`)\n",
        f"{r.get('architecture', 'A decoder-only transformer')}, **{r['parameters'] / 1e6:.1f}M parameters**, "
        f"trained from random initialisation on `{r['device']}`: {steps['pretrain']:,} pretraining steps, then "
        f"{steps.get('sft', 0):,} instruction-tuning steps.\n",
        f"**Corpus** (cleaned and deduplicated): {c['documents']:,} documents — "
        + ", ".join(f"{k} {v:,}" for k, v in c["by_source"].items())
        + f". {c['held_out_documents']:,} held out by document; {c['train_tokens']:,} training tokens.\n",
        "## Language modelling, held-out documents\n",
        "| Measure | Value |",
        "|---|---:|",
        f"| Loss | {h['loss']} |",
        f"| Perplexity (own tokens) | {h['perplexity']} |",
        f"| Bits per byte | {h['bits_per_byte']} |",
        "",
        "## Its own tokenizer\n",
        "| Tokenizer | Vocabulary | Tokens per held-out line |",
        "|---|---:|---:|",
        f"| **Kushmanda BPE** | {t['vocab']:,} | {t['tokens_per_line_held_out']} |",
        f"| GPT-2 (generic) | 50,257 | {gpt2 if gpt2 is not None else '—'} |",
        "",
    ]
    s = r.get("sft")
    if s:
        out += [
            "## Instruction tuning — held out by entity\n",
            f"{s['train_pairs']:,} training pairs, {s['held_out_pairs']:,} held-out pairs about techniques, CVEs and "
            f"CWEs never seen in tuning. Held-out answer loss: {s['held_out_answer_loss']}.\n",
            "| Question type | Exact-match accuracy | n |",
            "|---|---:|---:|",
            *[f"| {k} | {v['accuracy']:.3f} | {v['n']} |" for k, v in s["exact_match"].items()],
            "",
            "### Examples (greedy, unedited)\n",
            *[f"- **Q:** {e['question']}\n  **Expected:** {e['expected']}\n  **Kushmanda:** {e['answer']}" for e in s["examples"]],
            "",
        ]
    out += [
        "## Free completions\n",
        "A small, narrow model: it knows the domain's language, but it is not a source of facts. That's why Sati "
        "never treats generated text as evidence (rule 1).\n",
        *[f"- **{x['prompt']}**{x['completion']}" for x in r["samples"]],
        "",
        "Designed, written and trained by an AI assistant under the owner's direction "
        "([adr/RealDataModels](../../adr/RealDataModels.md)). Includes MITRE ATT&CK, CAPEC and CWE content, "
        "© The MITRE Corporation, used under MITRE's royalty-free licences.",
    ]
    print("\n".join(out))
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1]))
